import '@servicenow/sdk/global'
import { StringColumn } from '@servicenow/sdk/core'
import { Subflow, FlowObject, wfa, action } from '@servicenow/sdk/automation'

export const labelCacheSubflow = Subflow(
    {
        $id: Now.ID['subflow_label_cache'],
        name: 'Subflow Label Cache - Input Variables',
        description: 'Tests label cache with subflow inputs',
        runAs: 'system',
        runWithRoles: [],
        flowPriority: 'MEDIUM',
        inputs: {
            requestId: StringColumn({
                mandatory: true,
                label: 'Request Identifier',
                max_length: 32,
            }),
            priority: StringColumn({
                mandatory: true,
                label: 'Priority Level',
                max_length: 20,
            }),
            assignee: FlowObject({
                label: 'Assignee Information',
                fields: {
                    name: StringColumn({
                        mandatory: true,
                        label: 'Full Name',
                        max_length: 100,
                    }),
                    email: StringColumn({
                        mandatory: true,
                        label: 'Email Address',
                        max_length: 100,
                    }),
                    department: StringColumn({
                        mandatory: false,
                        label: 'Department',
                        max_length: 50,
                    }),
                },
            }),
        },
        outputs: {},
    },
    (params) => {
        wfa.action(
            action.core.log,
            { $id: Now.ID['subflow_action_step1'] },
            {
                log_message: `Request: ${wfa.dataPill(params.inputs.requestId, 'string')}, Priority: ${wfa.dataPill(params.inputs.priority, 'string')}, Email: ${wfa.dataPill(params.inputs.assignee.email, 'string')}`,
                log_level: 'info',
            }
        )

        wfa.flowLogic.if(
            {
                $id: Now.ID['subflow_step2'],
                condition: `${wfa.dataPill(params.inputs.assignee.department, 'string')}!=null`,
                annotation: 'Check if department exists',
            },
            () => {
                wfa.action(
                    action.core.log,
                    { $id: Now.ID['subflow_action_step3'] },
                    {
                        log_message: `Assignee: ${wfa.dataPill(params.inputs.assignee.name, 'string')}, Dept: ${wfa.dataPill(params.inputs.assignee.department, 'string')}`,
                        log_level: 'info',
                    }
                )
            }
        )
    }
)
